<script lang="ts">
 import {prefersReducedMotion} from 'svelte/motion';import {tick} from 'svelte';
 let {text,reduced=false}:{text:string;reduced?:boolean}=$props();const baseId=$props.id();const id='stroke-'+baseId.replace(/[^a-zA-Z0-9_-]/g,'');
 let iteration=$state(0),drawing=$state(false),previous='';let quiet=$derived(reduced||prefersReducedMotion.current);
 function redraw(){if(quiet)return;drawing=true;iteration++;}
 $effect(()=>{if(previous&&previous!==text)void tick().then(redraw);previous=text;});
 $effect(()=>{if(quiet)drawing=false;});
</script>
<button type="button" class="stroke-place-title" aria-label={text+'，点亮文字'} title="点亮此刻的小岛" data-effect="stroke-text" data-drawing={drawing} onpointerenter={redraw} onfocus={redraw} onclick={redraw}>
 <span class="sr-only">{text}</span>{#key iteration}<svg viewBox={'0 0 '+(Array.from(text).length*26+8)+' 36'} width={Array.from(text).length*26+8} height="32" aria-hidden="true" class:drawing class:quiet onanimationend={event=>{if(event.animationName.includes('stroke-fill'))drawing=false;}}><defs><clipPath {id}><rect class="stroke-wipe" width="100%" height="36"/></clipPath></defs><text class="stroke-readable" x="4" y="27" fill="currentColor" opacity=".7" font-size="24" font-weight="650">{#each Array.from(text) as char,i}<tspan x={4+i*26}>{char}</tspan>{/each}</text><text class="stroke-outline" x="4" y="27" fill="none" stroke="var(--xy-accent)" stroke-width=".9" stroke-linejoin="bevel" font-size="24" font-weight="650">{#each Array.from(text) as char,i}<tspan x={4+i*26} style:--glyph={i}>{char}</tspan>{/each}</text><text class="stroke-fill" x="4" y="27" fill="currentColor" clip-path={'url(#'+id+')'} font-size="24" font-weight="650">{#each Array.from(text) as char,i}<tspan x={4+i*26}>{char}</tspan>{/each}</text></svg>{/key}
</button>
<style>.stroke-place-title{display:block;max-width:100%;min-height:36px;padding:0;border:0;background:transparent;color:var(--xy-ink);cursor:pointer;border-radius:5px}.stroke-place-title svg{display:block;max-width:100%;overflow:visible;font-family:inherit}.stroke-wipe{transform-origin:left center}.drawing .stroke-outline tspan{stroke-dasharray:180;animation:stroke-draw .65s cubic-bezier(.2,0,0,1) both;animation-delay:calc(var(--glyph)*.025s)}.drawing .stroke-wipe{animation:stroke-fill .72s cubic-bezier(.2,0,0,1) both}.stroke-place-title:active{scale:.96}.quiet .stroke-outline tspan,.quiet .stroke-wipe{animation:none}@keyframes stroke-draw{from{stroke-dashoffset:180;opacity:.75}to{stroke-dashoffset:0;opacity:1}}@keyframes stroke-fill{0%,20%{transform:scaleX(0)}100%{transform:scaleX(1)}}@media(prefers-reduced-motion:reduce){.drawing .stroke-outline tspan,.drawing .stroke-wipe{animation:none}.stroke-place-title:active{scale:1}}</style>
